fn fibonacci(n: usize) -> Vec<i32> {
    // Since n >= 2, we can safely initialize with the first two Fibonacci numbers
    let mut result = Vec::with_capacity(n);
    
    // Push F(0) = 0
    result.push(0);
    
    // Push F(1) = 1
    result.push(1);
    
    // Generate the remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}